//! 🧪️ The actual child checkpoint source skips clean rows and preserves original authored metadata through a paid pin handoff.
use super::*;
use store::SpaceMember;
use semio_framework_plugin_job::reserved_jobs::child_vcs::checkpoint::{ChildCheckpointUnit as Unit,CheckpointMetadata};
use semio_framework_value::retained_clone::RetainedCloneSource;
#[test]fn original_child_checkpoint_preparation_uses_original_metadata_and_native_pin(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cut in law["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:4096,maximum_capacity_bytes:16<<20,..TURN};let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(result,&mut caller,&mut decoder);let message=law["message"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let pointer=message.as_ptr();let mut metadata=Some((Some(message),Vec::<protocol::Author>::new()));let mut original=None;let birth=RetainedCloneSource::<CheckpointMetadata>::owned_constructor_demand::<()>();let d=RetirementDemand{capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()};turn(&mut caller,&mut decoder,g,|cx|{let grant=cx.retained_grant();admit_original_construction(cx,&mut original,OriginalConstructionDemand{items:1,copy_bytes:0,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|RetainedCloneSource::admit_owned(metadata.take().unwrap(),(),grant).map_err(|(error,value,())|{metadata=Some(value);error}))?;Ok(())});let mut source=None;let d=Unit::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Unit::admit(cx,&mut source)?);Ok(())});assert!(source.is_none());}turn(&mut caller,&mut decoder,g,|cx|{assert!(Unit::admit(cx,&mut source)?);Ok(())});for index in 0..262144{if cut==Some(index)||source.as_ref().unwrap().ready(){break}let selected=source.as_ref().unwrap().next_construction_demands(&*store);let mut admitted=g;if let Some(d)=selected{admitted.maximum_copy_bytes=admitted.maximum_copy_bytes.max(d.copy_bytes);admitted.maximum_capacity_bytes=admitted.maximum_capacity_bytes.max(d.capacity_bytes);admitted.maximum_depth=admitted.maximum_depth.max(d.depth);}turn(&mut caller,&mut decoder,admitted,|cx|source.as_mut().unwrap().advance(&mut *store,original.as_ref().unwrap(),cx).map_err(|e|panic!("actual child checkpoint {:?}: {e:?}",source.as_ref().unwrap().progress())));assert!(index<262143,"actual child checkpoint stalled {:?} store capture {:?}",source.as_ref().unwrap().progress(),store.member_native_vcs_capture_demands());}if cut.is_none(){let mut pin=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(source.as_mut().unwrap().take_pin(cx,&mut pin)?);Ok(())});let(changed,pin)=pin.unwrap();assert!(changed);let pin=pin.unwrap();assert_eq!(pin.checkpoint_id,store.current_checkpoint_id().unwrap());assert_eq!(pin.child_ref.artifact_id,store.parts_ref().log.envelope.id);assert_eq!(original.as_ref().unwrap().try_authority().unwrap().0.as_ref().unwrap().as_ptr(),pointer);assert_eq!(store.parts_ref().log.envelope.vcs.checkpoints.get(0).unwrap().message,original.as_ref().unwrap().try_authority().unwrap().0);close_typed(pin,&mut caller,&mut decoder);}else{caller.cancel().cancel_now();}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(&mut *store,cx)));assert!(index<262143);}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Unit::release_demands();close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));for index in 0..262144{if original.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=original.as_ref().unwrap().next_close_demand(4096)?;close_original_retained_step(cx,d,|grant|original.as_mut().unwrap().close_step(grant))?;Ok(())}));assert!(index<262143);}original.take();for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
